return {
  name: node.properties.toolName?.value || 'get_datetime',
  description: node.properties.toolDescription?.value || 'Get current date/time',
  enabled: node.properties.enabled?.value !== false,
  schema: {
    type: 'object',
    properties: {
      timezone: {
        type: 'string',
        description: 'Timezone (e.g., "America/New_York", "Europe/London", default: "UTC")'
      },
      format: {
        type: 'string',
        description: 'Date format ("ISO", "locale", or custom format)'
      }
    }
  },
  code: `const now = new Date();
const timezone = args.timezone || 'UTC';
const format = args.format || 'ISO';
const result = {
  iso: now.toISOString(),
  unix: Math.floor(now.getTime() / 1000),
  timestamp: now.getTime(),
  timezone
};
if (format !== 'ISO') {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });
  result.formatted = formatter.format(now);
} else {
  result.formatted = now.toISOString();
}
return result;`
};
